    'hero.proof1': 'Starting with weight loss', 'hero.proof2': 'Organizing the journey', 'hero.proof3': 'An evolving experience', 'hero.demoAria': 'REROUTE demonstration',
    'hero.next': 'The navigation concept', 'hero.message': 'An achievable next step', 'hero.messageBody': 'Destination, route, action and reflection: REROUTE is about organizing the journey and making room to change course when needed.', 'hero.signature': 'Weight loss is the goal. Organization is the route.', 'hero.formKicker': 'FREE ACCESS', 'hero.formTitle': 'I want access to REROUTE', 'hero.formLead': 'Sign up for free. We are releasing new access gradually.', 'hero.formPhoneNote': 'We will use your WhatsApp to contact you about REROUTE.', 'hero.formPrivacy': 'Your details will be used to contact you about REROUTE. By submitting, you agree to our.', 'hero.formSpeed': 'Takes less than 30 seconds.', 'hero.formSubmit': 'I WANT TO JOIN', 'hero.formNote': 'Already signed up? Keep an eye on your inbox. Your access may be among the next releases.', 'hero.login': 'Already received access? Enter REROUTE →',
