    'demo.open': 'Explore the interactive REROUTE demo', 'demo.click': 'Click to explore', 'demo.touch': 'Tap to explore', 'demo.close': 'Close demo', 'demo.step': 'STEP {current} OF {total}',
    'demo.title1': 'What is your destination?', 'demo.description1': 'It all starts with understanding where you want to go. REROUTE turns your goal into a clear destination.',
    'demo.title2': 'Tell us about your current moment', 'demo.description2': 'Your routine, your time, and your reality help REROUTE understand where you are starting from.',
